package com.campusradar.social;

import com.campusradar.common.*;
import org.springframework.stereotype.Service;
import java.sql.Timestamp;
import java.time.*;
import java.util.*;
import static com.campusradar.common.SqlRows.map;

@Service
public class SocialService {
    public final SqlRows sql;
    public SocialService(SqlRows sql){this.sql=sql;}
    static final String BASE="id,version,created_at,updated_at";
    static final String POST="p.id,p.version,p.created_at,p.updated_at,p.body_md,p.tags,p.author_id,p.status";
    static final String ROOM="r.id,r.version,r.created_at,r.updated_at,r.owner_id,r.name,r.description,r.visibility,r.capacity,r.state";
    static final String INVITE=BASE+",room_id,inviter_id,invitee_id,state,expires_at";
    static final String COMMENT=BASE+",author_id,body,status,parent_id";
    static final String REQUEST="q.id,q.version,q.created_at,q.updated_at,q.referral_id,q.applicant_id,q.message,q.status,q.reply";
    static final String REFERRAL="r.id,r.version,r.created_at,r.updated_at,r.company_id,r.job_id,r.title,r.description,r.expires_at,r.provider_id,r.status";
    static final String ACTIVE_PROVIDER="u.status='ACTIVE' AND u.provider_verified=1 AND u.provider_verified_until>CURRENT_TIMESTAMP";
    public static void page(int page,int size){if(page<1||page>500||size<1||size>100)throw invalid("分页参数无效。");}
    public static ApiProblem invalid(String message){return new ApiProblem(422,"VALIDATION_ERROR",message);}
    public static ApiProblem missing(){return new ApiProblem(404,"NOT_FOUND","记录不存在或不可访问。");}
    public static ApiProblem forbidden(){return new ApiProblem(403,"FORBIDDEN","你没有操作此记录的权限。");}
    public static void version(Map<String,Object> row,int expected){if(((Number)row.get("version")).intValue()!=expected)throw new ApiProblem(409,"VERSION_CONFLICT","记录已更新，请刷新后重试。");}
    public Map<String,Object> insert(String table,Map<String,Object>b){if(!Set.of("posts","comments","buddy_rooms","buddy_members","buddy_invitations","buddy_tasks","buddy_task_progress","referrals","referral_requests","content_reports").contains(table))throw new IllegalArgumentException();String id=UUID.randomUUID().toString();var p=map("id",id);var cols=new StringBuilder("id");var vals=new StringBuilder(":id");int i=0;for(var e:b.entrySet()){String col=SqlRows.snake(e.getKey()),param="v"+i++;cols.append(',').append(col);vals.append(",:").append(param);p.put(param,sql.value(col,e.getValue(),Set.of("tags")));}sql.db.update("INSERT INTO "+table+" ("+cols+") VALUES("+vals+")",p);return map("id",id);}
    public Map<String,Object> post(String user,String id,boolean own){String where=own?"p.author_id=:u":"p.status='PUBLISHED'";var row=sql.one("SELECT "+POST+" FROM posts p WHERE p.id=:id AND "+where,map("id",id,"u",user),Set.of("tags"),Set.of());return postCounts(user,row);}
    Map<String,Object> postCounts(String user,Map<String,Object>row){var p=map("id",row.get("id"),"u",user);row.put("likeCount",sql.db.queryForObject("SELECT COUNT(*) FROM post_likes WHERE post_id=:id",p,Integer.class));row.put("commentCount",sql.db.queryForObject("SELECT COUNT(*) FROM comments WHERE post_id=:id AND status='PUBLISHED'",p,Integer.class));row.put("likedByMe",user!=null&&sql.db.queryForObject("SELECT COUNT(*) FROM post_likes WHERE post_id=:id AND user_id=:u",p,Integer.class)>0);return row;}
    public Map<String,Object> createPost(String user,Map<String,Object>b){var value=new LinkedHashMap<>(b);value.put("authorId",user);value.put("status","PENDING");return post(user,insert("posts",value).get("id").toString(),true);}
    public Map<String,Object> patchPost(String user,String id,Map<String,Object>b){version(post(user,id,true),((Number)b.get("version")).intValue());var old=post(user,id,true);old.putAll(b);sql.db.update("UPDATE posts SET body_md=:body,tags=:tags,status='PENDING',published_at=NULL,version=version+1,updated_at=CURRENT_TIMESTAMP WHERE id=:id",map("id",id,"body",old.get("bodyMd"),"tags",sql.json.writeValueAsString(old.get("tags"))));return post(user,id,true);}
    public Object deletePost(String user,String id,int version){version(post(user,id,true),version);var p=map("id",id);sql.db.update("UPDATE comments SET parent_id=NULL WHERE post_id=:id",p);sql.db.update("DELETE FROM comments WHERE post_id=:id",p);sql.db.update("DELETE FROM post_likes WHERE post_id=:id",p);sql.db.update("DELETE FROM posts WHERE id=:id",p);return null;}
    public Object like(String user,String id,boolean liked){post(user,id,false);var p=map("id",id,"u",user);if(liked){if(sql.db.queryForObject("SELECT COUNT(*) FROM post_likes WHERE post_id=:id AND user_id=:u",p,Integer.class)==0)sql.db.update("INSERT INTO post_likes(post_id,user_id) VALUES(:id,:u)",p);}else sql.db.update("DELETE FROM post_likes WHERE post_id=:id AND user_id=:u",p);return null;}
    String topic(String type){if(type.equals("posts"))return "post_id";if(type.equals("experiences"))return "experience_id";throw missing();}
    void publishedTopic(String type,String id){if(sql.db.queryForObject("SELECT COUNT(*) FROM "+(type.equals("posts")?"posts":"experiences")+" WHERE id=:id AND status='PUBLISHED'",map("id",id),Integer.class)==0)throw missing();}
    public Map<String,Object> comment(String user,String type,String id,Map<String,Object>b){String col=topic(type);publishedTopic(type,id);if(b.get("parentId")!=null&&sql.db.queryForObject("SELECT COUNT(*) FROM comments WHERE id=:parent AND "+col+"=:id AND status='PUBLISHED'",map("parent",b.get("parentId"),"id",id),Integer.class)==0)throw invalid("父评论必须属于相同的公开内容。");var v=map("authorId",user,"body",b.get("body"),"parentId",b.get("parentId"),"status","PUBLISHED");v.put(type.equals("posts")?"postId":"experienceId",id);String comment=insert("comments",v).get("id").toString();return sql.one("SELECT "+COMMENT+" FROM comments WHERE id=:id",map("id",comment),Set.of(),Set.of());}
    public Map<String,Object> ownComment(String user,String type,String topicId,String commentId){return sql.one("SELECT "+COMMENT+" FROM comments WHERE id=:comment AND author_id=:u AND "+topic(type)+"=:topic",map("comment",commentId,"u",user,"topic",topicId),Set.of(),Set.of());}
    public Object deleteComment(String user,String type,String id,String comment,int expected){
        String col=topic(type);sql.one("SELECT id FROM comments WHERE id=:comment AND "+col+"=:id AND author_id=:u",map("id",id,"comment",comment,"u",user),Set.of(),Set.of());return withdrawComment(user,comment,expected);
    }
    public Object withdrawComment(String user,String comment,int expected){
        var p=map("comment",comment,"u",user,"version",expected);var row=sql.one("SELECT "+COMMENT+" FROM comments WHERE id=:comment AND author_id=:u",p,Set.of(),Set.of());version(row,expected);
        if("HIDDEN".equals(row.get("status"))&&"".equals(row.get("body")))throw new ApiProblem(409,"INVALID_STATE","评论已撤回或删除。");
        if(sql.db.update("UPDATE comments SET body='',status='HIDDEN',version=version+1,updated_at=CURRENT_TIMESTAMP WHERE id=:comment AND author_id=:u AND version=:version",p)!=1)throw new ApiProblem(409,"VERSION_CONFLICT","评论已变化，请刷新后重试。");return null;
    }
    public Map<String,Object> room(String id,boolean lock){var r=sql.one("SELECT "+ROOM+" FROM buddy_rooms r WHERE r.id=:id"+(lock?" FOR UPDATE":""),map("id",id),Set.of(),Set.of());r.put("memberCount",sql.db.queryForObject("SELECT COUNT(*) FROM buddy_members WHERE room_id=:id",map("id",id),Integer.class));return r;}
    private void owner(String user,Map<String,Object>room){if(!user.equals(room.get("ownerId")))throw forbidden();}
    private void open(Map<String,Object>room){if(!"OPEN".equals(room.get("state")))throw new ApiProblem(409,"ROOM_CLOSED","房间已关闭。");}
    public Map<String,Object> member(String user,String room){return sql.one("SELECT m.id,m.version,m.created_at,m.updated_at,m.user_id,u.display_name,m.role,m.joined_at FROM buddy_members m JOIN users u ON u.id=m.user_id WHERE m.room_id=:room AND m.user_id=:u",map("room",room,"u",user),Set.of(),Set.of());}
    private Map<String,Object> addMember(String user,Map<String,Object>room){String id=room.get("id").toString();if(sql.db.queryForObject("SELECT COUNT(*) FROM buddy_members WHERE room_id=:room AND user_id=:u",map("room",id,"u",user),Integer.class)>0)return member(user,id);if(((Number)room.get("memberCount")).intValue()>=((Number)room.get("capacity")).intValue())throw new ApiProblem(409,"ROOM_FULL","房间已满员。");insert("buddy_members",map("roomId",id,"userId",user,"role",user.equals(room.get("ownerId"))?"OWNER":"MEMBER","joinedAt",Instant.now().toString()));return member(user,id);}
    public Map<String,Object> createRoom(String user,Map<String,Object>b){var value=new LinkedHashMap<>(b);value.put("ownerId",user);value.put("state","OPEN");String id=insert("buddy_rooms",value).get("id").toString();addMember(user,room(id,true));return room(id,false);}
    public Map<String,Object> join(String user,String id){var r=room(id,true);open(r);if(!"PUBLIC".equals(r.get("visibility")))throw forbidden();return addMember(user,r);}
    public Object leave(String user,String id){var r=room(id,true);member(user,id);if(user.equals(r.get("ownerId"))&&"OPEN".equals(r.get("state")))throw new ApiProblem(409,"OWNER_MUST_CLOSE","房主须先关闭房间再离开。");var p=map("room",id,"u",user);sql.db.update("DELETE FROM buddy_task_progress WHERE room_id=:room AND user_id=:u",p);sql.db.update("DELETE FROM buddy_members WHERE room_id=:room AND user_id=:u",p);return map("accepted",true);}
    public Map<String,Object> close(String user,String id,int expected){var r=room(id,true);owner(user,r);version(r,expected);sql.db.update("UPDATE buddy_rooms SET state='CLOSED',version=version+1,updated_at=CURRENT_TIMESTAMP WHERE id=:id",map("id",id));sql.db.update("UPDATE buddy_invitations SET state='EXPIRED',expires_at=CURRENT_TIMESTAMP,version=version+1,updated_at=CURRENT_TIMESTAMP WHERE room_id=:id AND state='PENDING'",map("id",id));return room(id,false);}
    public List<Map<String,Object>> members(String user,String id){member(user,id);return sql.query("SELECT m.id,m.version,m.created_at,m.updated_at,m.user_id,u.display_name,m.role,m.joined_at FROM buddy_members m JOIN users u ON u.id=m.user_id WHERE m.room_id=:id ORDER BY m.joined_at,m.id",map("id",id));}
    public Map<String,Object> invite(String user,String id,String invitee){var r=room(id,true);owner(user,r);open(r);if(sql.db.queryForObject("SELECT COUNT(*) FROM users WHERE id=:u AND status='ACTIVE'",map("u",invitee),Integer.class)==0)throw missing();if(user.equals(invitee)||sql.db.queryForObject("SELECT COUNT(*) FROM buddy_members WHERE room_id=:id AND user_id=:u",map("id",id,"u",invitee),Integer.class)>0)throw new ApiProblem(409,"ALREADY_MEMBER","此用户已经在房间中。");if(sql.db.queryForObject("SELECT COUNT(*) FROM buddy_invitations WHERE room_id=:id AND invitee_id=:u AND state='PENDING' AND expires_at>CURRENT_TIMESTAMP",map("id",id,"u",invitee),Integer.class)>0)throw new ApiProblem(409,"INVITATION_EXISTS","此用户已有待处理邀请。");String invitation=insert("buddy_invitations",map("roomId",id,"inviterId",user,"inviteeId",invitee,"state","PENDING","expiresAt",Instant.now().plusSeconds(7*86400).toString())).get("id").toString();return invitation(user,invitation,false);}
    Map<String,Object> invitation(String user,String id,boolean recipient){return sql.one("SELECT "+INVITE+" FROM buddy_invitations WHERE id=:id AND "+(recipient?"invitee_id=:u":"inviter_id=:u"),map("id",id,"u",user),Set.of(),Set.of());}
    public Map<String,Object> inviteAction(String user,String id,int expected,String action){var invitation=invitation(user,id,true);var r=room(invitation.get("roomId").toString(),true);version(invitation,expected);if(!"PENDING".equals(invitation.get("state"))||!Instant.parse(invitation.get("expiresAt").toString()).isAfter(Instant.now()))throw new ApiProblem(409,"INVITATION_EXPIRED","邀请已处理或过期。");if(action.equals("ACCEPT")){open(r);addMember(user,r);}sql.db.update("UPDATE buddy_invitations SET state=:state,version=version+1,updated_at=CURRENT_TIMESTAMP WHERE id=:id",map("id",id,"state",action.equals("ACCEPT")?"ACCEPTED":"DECLINED"));return invitation(user,id,true);}
    public List<Map<String,Object>> tasks(String user,String id){member(user,id);return sql.query("SELECT t.*,CASE WHEN p.completed=1 THEN 1 ELSE 0 END completed_by_me FROM buddy_tasks t LEFT JOIN buddy_task_progress p ON p.task_id=t.id AND p.user_id=:u WHERE t.room_id=:id ORDER BY t.created_at,t.id LIMIT 100",map("u",user,"id",id),Set.of(),Set.of("completed_by_me"));}
    public Map<String,Object> createTask(String user,String id,Map<String,Object>b){var r=room(id,true);owner(user,r);open(r);if(b.get("questionId")!=null&&sql.db.queryForObject("SELECT COUNT(*) FROM questions WHERE id=:id AND status='PUBLISHED'",map("id",b.get("questionId")),Integer.class)==0)throw missing();if(sql.db.queryForObject("SELECT COUNT(*) FROM buddy_tasks WHERE room_id=:id",map("id",id),Integer.class)>=100)throw new ApiProblem(409,"TASK_LIMIT","房间最多保存100项共享任务。");var v=new LinkedHashMap<>(b);v.put("roomId",id);String task=insert("buddy_tasks",v).get("id").toString();return tasks(user,id).stream().filter(t->task.equals(t.get("id"))).findFirst().orElseThrow();}
    public Object progress(String user,String id,String task,boolean completed){var r=room(id,true);open(r);member(user,id);var p=map("room",id,"task",task,"u",user,"completed",completed);if(sql.db.queryForObject("SELECT COUNT(*) FROM buddy_tasks WHERE id=:task AND room_id=:room",p,Integer.class)==0)throw missing();if(sql.db.queryForObject("SELECT COUNT(*) FROM buddy_task_progress WHERE task_id=:task AND user_id=:u",p,Integer.class)==0)insert("buddy_task_progress",map("roomId",id,"taskId",task,"userId",user,"completed",completed));else sql.db.update("UPDATE buddy_task_progress SET completed=:completed,version=version+1,updated_at=CURRENT_TIMESTAMP WHERE task_id=:task AND user_id=:u",p);return tasks(user,id).stream().filter(t->task.equals(t.get("id"))).findFirst().orElseThrow();}
    public Map<String,Object> referral(String id,boolean published){return sql.one("SELECT "+REFERRAL+",CASE WHEN "+ACTIVE_PROVIDER+" THEN 1 ELSE 0 END provider_verified FROM referrals r JOIN users u ON u.id=r.provider_id WHERE r.id=:id"+(published?" AND r.status='PUBLISHED' AND r.expires_at>CURRENT_TIMESTAMP AND "+ACTIVE_PROVIDER:""),map("id",id),Set.of(),Set.of("provider_verified"));}
    public Map<String,Object> createReferral(String user,Map<String,Object>b){if(sql.db.queryForObject("SELECT COUNT(*) FROM users u WHERE u.id=:id AND "+ACTIVE_PROVIDER,map("id",user),Integer.class)==0)throw forbidden();if(!Instant.parse(b.get("expiresAt").toString()).isAfter(Instant.now()))throw invalid("内推资源有效期须在未来。");if(sql.db.queryForObject("SELECT COUNT(*) FROM companies WHERE id=:id",map("id",b.get("companyId")),Integer.class)==0)throw missing();if(b.get("jobId")!=null&&sql.db.queryForObject("SELECT COUNT(*) FROM jobs j JOIN sources s ON s.id=j.source_id WHERE j.id=:id AND j.company_id=:company AND j.publication_status='PUBLISHED' AND s.enabled=1",map("id",b.get("jobId"),"company",b.get("companyId")),Integer.class)==0)throw invalid("岗位须属于所选公司且公开可用。");var v=new LinkedHashMap<>(b);v.put("providerId",user);v.put("status","PENDING");return referral(insert("referrals",v).get("id").toString(),false);}
    public Map<String,Object> createRequest(String user,String referral,Map<String,Object>b){var r=referral(referral,true);if(user.equals(r.get("providerId")))throw invalid("不能申请自己提供的内推。");if(sql.db.queryForObject("SELECT COUNT(*) FROM referral_requests WHERE referral_id=:id AND applicant_id=:u",map("id",referral,"u",user),Integer.class)>0)throw new ApiProblem(409,"REQUEST_EXISTS","已申请此内推资源。");String id=insert("referral_requests",map("referralId",referral,"applicantId",user,"message",b.get("message"),"status","PENDING","reply","","consentAt",Instant.now().toString())).get("id").toString();return request(user,id);}
    public Map<String,Object> request(String user,String id){return sql.one("SELECT "+REQUEST+" FROM referral_requests q JOIN referrals r ON r.id=q.referral_id WHERE q.id=:id AND (q.applicant_id=:u OR r.provider_id=:u)",map("id",id,"u",user),Set.of(),Set.of());}
    public Map<String,Object> patchRequest(String user,String id,Map<String,Object>b){var q=sql.one("SELECT "+REQUEST+" FROM referral_requests q JOIN referrals r ON r.id=q.referral_id WHERE q.id=:id AND (q.applicant_id=:u OR r.provider_id=:u) FOR UPDATE",map("id",id,"u",user),Set.of(),Set.of());version(q,((Number)b.get("version")).intValue());if(!"PENDING".equals(q.get("status")))throw new ApiProblem(409,"REQUEST_FINAL","申请已处理。");boolean applicant=user.equals(q.get("applicantId"));String status=b.get("status").toString();if(applicant&&!status.equals("CANCELLED")||!applicant&&status.equals("CANCELLED"))throw forbidden();if(applicant&&b.containsKey("reply"))throw invalid("申请者不能填写提供者回复。");sql.db.update("UPDATE referral_requests SET status=:status,reply=:reply,version=version+1,updated_at=CURRENT_TIMESTAMP WHERE id=:id",map("id",id,"status",status,"reply",b.getOrDefault("reply",q.get("reply"))));return request(user,id);}
    public Map<String,Object> report(String user,Map<String,Object>b){String target=b.get("targetType").toString(),id=b.get("targetId").toString();String query=switch(target){case "JOB"->"SELECT COUNT(*) FROM jobs j JOIN sources s ON s.id=j.source_id WHERE j.id=:id AND j.publication_status='PUBLISHED' AND s.enabled=1";case "EXPERIENCE"->"SELECT COUNT(*) FROM experiences WHERE id=:id AND status='PUBLISHED'";case "QUESTION"->"SELECT COUNT(*) FROM questions WHERE id=:id AND status='PUBLISHED'";case "CHAPTER"->"SELECT COUNT(*) FROM chapters WHERE id=:id AND status='PUBLISHED'";case "POST"->"SELECT COUNT(*) FROM posts WHERE id=:id AND status='PUBLISHED'";case "EXPERIENCE_COMMENT"->"SELECT COUNT(*) FROM comments c JOIN experiences e ON e.id=c.experience_id WHERE c.id=:id AND c.status='PUBLISHED' AND e.status='PUBLISHED'";case "POST_COMMENT"->"SELECT COUNT(*) FROM comments c JOIN posts p ON p.id=c.post_id WHERE c.id=:id AND c.status='PUBLISHED' AND p.status='PUBLISHED'";case "REFERRAL"->"SELECT COUNT(*) FROM referrals r JOIN users u ON u.id=r.provider_id WHERE r.id=:id AND r.status='PUBLISHED' AND r.expires_at>CURRENT_TIMESTAMP AND "+ACTIVE_PROVIDER;case "SALARY"->"SELECT COUNT(*) FROM salary_reports WHERE id=:id AND status='PUBLISHED'";case "SIGNAL"->"SELECT COUNT(*) FROM radar_signals WHERE id=:id AND status='PUBLISHED'";default->throw invalid("举报类型无效。");};if(sql.db.queryForObject(query,map("id",id),Integer.class)==0)throw missing();var v=new LinkedHashMap<>(b);v.put("userId",user);v.put("state","OPEN");String report=insert("content_reports",v).get("id").toString();return sql.one("SELECT "+BASE+",target_type,target_id,reason,state FROM content_reports WHERE id=:id",map("id",report),Set.of(),Set.of());}
}
